xml.Script:
        W := 0.6;
        N := 3;
        D := W / N;
        WX := D;
        WY := D;
        WZ := D;

        S[0] := ' 1 |1 1| 1 ';
        S[1] := '111|111|111';
        S[2] := '   |   |   ';

        function GetType(x1, y1, z1);
        begin
            Result := copy(S[N-1-z1], (N + 1) * y1 + x1 + 1, 1);
        end;

        procedure CalcCubie(No);
        begin
            x := No mod N;
            y := No div N mod N;
            z := No div N div N;
            CType := GetType(x,y,z);
            if CType <> ' ' then begin 
                DWX := D * (2 * x - N + 1);
                DWY := D * (2 * y - N + 1);
                DWZ := D * (2 * z - N + 1);
                CCount := 1;
            end else
                CCount := 0;
        end;
